/** WS-REG-DET-INFOICA: detalle de 160 posiciones del archivo INFOICA. */
public record MovimientoIca(
        int csiOrigen,                 // 9(02) · válidos: p115.csis-validos
        int nodoOrigen,
        int csiDestino,
        String estacion,               // X(08): tipo-disp(1) + sucursal 9(4) + caja X(3)
        LocalDate fechaGeneracion,     // 9(08) AAAAMMDD
        LocalTime horaGeneracion,      // 9(06) HHMMSS
        int aplOrigen, int aplDestino, // 9(04): sistema origen y destino
        EstatusTransaccion estatus,
        CodigoServicio servicio,
        int subServicio,
        String cuentaDestino,          // X(20): se conserva como texto (sucursal 9(4) + cuenta 9(7) al final)
        BigDecimal importe,            // 9(16)V99 -> escala 2
        int moneda,                    // 9(03)
        LocalDate fechaContable,       // 9(08) AAAAMMDD
        String claveAutorizacion,      // X(20)
        long numTransaccion,
        String cuentaAcceso, String referencia,
        String raw) {

    public String sucursalOrigen() { return estacion.substring(1, 5); }
}

/** Niveles 88 de WS-RDI-STA-TRN. */
public enum EstatusTransaccion {
    ENVIADO(1), APLICADO(2), OPERADO(3), DENEGADO(4), PENDIENTE(5), INVALIDO(-1);
    final int codigo;
    EstatusTransaccion(int c) { codigo = c; }
    static EstatusTransaccion of(int c) {
        return Arrays.stream(values()).filter(e -> e.codigo == c).findFirst().orElse(INVALIDO);
    }
}

/** Niveles 88 de WS-RDI-COD-SER: 10 cargo, 20 abono, 11 y 21 eliminaciones. */
public enum CodigoServicio {
    CARGO(10), ABONO(20), ELIM_CARGO(11), ELIM_ABONO(21), INVALIDO(-1);
    final int codigo;
    CodigoServicio(int c) { codigo = c; }
    static CodigoServicio of(int c) {
        return Arrays.stream(values()).filter(e -> e.codigo == c).findFirst().orElse(INVALIDO);
    }
}

