@Component
@StepScope
@RequiredArgsConstructor
public class EnlaceS028Writer implements ItemStreamWriter<TotalTerminal> {

    private final FlatFileItemWriter<RegistroS028> salida;   // TRANSMISION X(60)
    private final P115Properties props;
    private long registros;                                   // WS-R028-TREG
    private BigDecimal totalCargos = BigDecimal.ZERO.setScale(2);   // WS-R028-TCAR
    private BigDecimal totalAbonos = BigDecimal.ZERO.setScale(2);   // WS-R028-TABO

    @Override
    public void open(ExecutionContext ctx) {                 // 24510-REG-CONTROL-S028
        salida.open(ctx);
        salida.write(Chunk.of(RegistroS028.control("HR", fechaProceso, LocalDateTime.now(),
                props.s028().sistema(), props.s028().nombre())));
    }

    @Override
    public void write(Chunk<? extends TotalTerminal> chunk) throws Exception {   // 24530-GRABA-S028
        for (var t : chunk) {
            var local = t.cifras(Ambito5.LOCAL);              // ACUM(1): solo operaciones locales
            salida.write(Chunk.of(RegistroS028.movimiento(t.llave(), local)));
            registros++;
            totalCargos = totalCargos.add(local.impCargos());
            totalAbonos = totalAbonos.add(local.impAbonos());
        }
    }
    // close(): 24560-REG-TRAILER-S028 con registros, totalCargos y totalAbonos.
}
